"""Snapping clock times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_clock
from hourglass.models import Span

def check_step(step: int) -> None:
    """Steps must divide an hour evenly."""
    if step <= 0 or 60 % step != 0:
        raise ValueError(
            f"step must divide an hour evenly: {step}"
        )

def round_minute(value: int, step: int) -> int:
    """Nearest multiple of step. Halves round up."""
    return (2 * value + step) // (2 * step) * step

def format_duration(minutes: int) -> str:
    hours, remainder = divmod(minutes, 60)
    return f"{hours}h {remainder}m"

# ---
def round_span(span: Span, step: int) -> Span:
    """Snap both ends of a span to the nearest step."""
    check_step(step)
    return Span(
        round_minute(span.start, step),
        round_minute(span.end, step)
    )

# ---
def rounded_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels such as 09:00-17:15 (8h 15m), one per span."""
    check_step(step)
    labels = []
    for span in spans:
        snapped = round_span(span, step)
        labels.append(
            f"{format_clock(snapped.start)}"
            f"-{format_clock(snapped.end)}"
            f" ({format_duration(snapped.minutes)})"
        )
    return labels

