import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        self.assertEqual(
            round_span(parse_span("09:07-17:08"), 15),
            parse_span("09:00-17:15")
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_span(parse_span("09:05-10:25"), 10),
            parse_span("09:10-10:30")
        )

    def test_span_collapsing_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(540, 544), 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        self.assertEqual(
            rounded_labels([parse_span("09:02-17:14")], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        labels = rounded_labels(
            [Span(540, 600), Span(601, 700)], 5
        )
        self.assertEqual(
            labels,
            ["09:00-10:00 (1h 0m)", "10:00-11:40 (1h 40m)"]
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_end_of_day(self):
        self.assertEqual(
            rounded_labels([parse_span("23:00-24:00")], 30),
            ["23:00-24:00 (1h 0m)"]
        )

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 61):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels([Span(540, 600)], step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                rounded_labels([Span(540, 600)], step)

if __name__ == "__main__":
    unittest.main()
